const makeResources = (subjectId, topicId) => publisherResources[subjectId].map(([title, source, url], index) => ({
  id: `study-${topicId}-${index + 1}`,
  type: "Recommended guide",
  title,
  source,
  url,
}));

const makeQuestions = (topicId, rows) => rows.map(([difficulty, prompt, options, answerIndex, explanation], index) => ({
  id: `${topicId}-practice-${String(index + 1).padStart(2, "0")}`,
  topic: topicId,
  difficulty,
  prompt,
  options,
  correctAnswer: options[answerIndex],
  explanation,
}));

const makeProblems = (topicId, topic, rows) => rows.map(([id, title, difficulty, slug]) => ({
  id,
  title,
  topic,
  platform: "LeetCode",
  difficulty,
  url: `https://leetcode.com/problems/${slug}/`,
}));

