    "classes-objects": { notes: ["A class defines a type's state and behavior; an object is a runtime instance of that class.", "Instance fields belong to each object; static members belong to the class itself.", "Prefer clear responsibilities and composition when an object needs collaborators rather than a deep inheritance tree."], resources: [{ id: "codearmy-oop-lessons", type: "Course", title: "CodeArmy OOP lessons", source: "CodeArmy" }], questions: makeQuestions("classes-objects", [["Easy", "What is an object in class-based programming?", ["An instance of a class", "A source file", "A compiler warning", "A package manager"], 0, "An object is a concrete instance with state and behavior defined by its class."], ["Easy", "An instance field normally stores:", ["State belonging to one object", "A global class name only", "The compiler version", "A network route"], 0, "Each object has its own instance state unless the field is shared through static/class semantics."], ["Medium", "Which relationship expresses a 'has-a' design most directly?", ["Composition", "Inheritance", "Overloading", "Casting"], 0, "Composition builds an object from collaborating parts instead of treating it as a subtype."]]) },
