export function applyStarterContent(subjects) {
  for (const subject of subjects) {
    for (const topic of subject.topics) {
      const content = topicContent[subject.id]?.[topic.id] ?? {};
      if (content.title) topic.title = content.title;
      if (content.notes) topic.notes = content.notes;
      const resources = [...(topic.resources ?? []), ...makeResources(subject.id, topic.id), ...(content.resources ?? [])];
      const existingResources = [...new Map(resources.map((resource) => [resource.id, resource])).values()];
      const curatedResources = getCuratedResources(subject.id, topic);
      topic.resources = curatedResources
        ? curatedResources.map((resource, index) => ({ ...resource, id: existingResources[index]?.id ?? resource.id }))
        : existingResources;
      topic.practice ??= { type: subject.id === "dsa" ? "coding" : "mcq", problems: [], questions: [] };
      const problems = [
        ...(topic.practice.problems ?? []),
        ...(content.problems ?? []),
        ...makeUpgradeProblems(topic.id, topic.title),
      ];
      const questions = [
        ...(topic.practice.questions ?? []),
        ...(content.questions ?? []).map((question) => ({ ...question, topic: topic.title })),
        ...(hardQuestionUpgrades[`${subject.id}:${topic.id}`] ?? []),
      ];
      topic.practice.problems = [...new Map(problems.map((problem) => [problem.id, problem])).values()];
      topic.practice.questions = [...new Map(questions.map((question) => [question.id, question])).values()];
      if (subject.id !== "dsa" && topic.practice.questions.length) topic.practice.type = "mcq";
      if (subject.id === "dsa" && topic.practice.problems.length) topic.practice.type = "coding";
    }
  }
}

